# Let me examine the connected components in the grid
def find_components(grid, color, include_bg=False):
    """Find all 2x1 connected components of a color"""
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    components = []
    color_to_find = color if color != 0 else (0 if include_bg else None)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color:
                # Check for 2x1 horizontal right or 2x1 vertical down
                if color == 0 and not include_bg:
                    continue  # Skip background
                is_horizontal = False
                is_vertical = False
                # Check right neighbor for horizontal pair
                if c + 1 < cols and grid[r][c+1] == color:
                    is_horizontal = True
                # Check down neighbor for vertical pair  
                if r + 1 < rows and grid[r+1][c] == color:
                    is_vertical = True

                if is_horizontal or is_vertical:
                    component = {'r': r, 'c': c, 'type': 'horizontal' if is_horizontal else 'vertical', 'cells': []}
                    component['cells'].append((r, c))
                    if is_horizontal:
                        component['cells'].append((r, c+1))
                    # Don't double-count vertical down (only count top of each vertical pair)

                    # Check if already visited
                    key = (component['r'], component['c'], component['type'])
                    if key not in visited:
                        visited.add(key)
                        components.append(component)

    return components

# Find all 2-cell components of each color
print("=== 2-cell horizontal/vertical pairs ===")
for color in [1, 2, 3, 4, 5, 6, 7, 8, 9]:
    components = find_components(input_grid, color)
    if components:
        print(f"Color {color}: {len(components)} pairs")
        for comp in components:
            print(f"  Type: {comp['type']}, at ({comp['r']}, {comp['c']})")

