                # Check if this cell would be part of a 2-cell pair
                in_pair = False
                # Check right
                if c + 1 < cols and input_grid[r][c+1] == color:
                    in_pair = True
                # Check down
                if r + 1 < rows and input_grid[r+1][c] == color:
