                # Check left
                if c - 1 >= 0 and input_grid[r][c-1] == color:
                    in_pair = True
                # Check up
                if r - 1 >= 0 and input_grid[r-1][c] == color:
                    in_pair = True
                # Check diagonal (could be 2-cell block)
                if r - 1 >= 0 and c - 1 >= 0 and input_grid[r-1][c-1] == color:
                    in_pair = True

    if singles:
        # Count instances per color
        color_count = 0
        for r, c in single_cells.keys():
            if single_cells[(r,c)] == color:
                color_count += 1
        if color_count > 0:
            print(f"Color {color}: {color_count} cells not in 2-cell pairs (locations: {[(r,c) for r,c in single_cells if single_cells[(r,c)]==color]})")

# Fix the bounds checking
def find_connected_objects(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    objects = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                obj = {'color': color, 'cells': [], 'r': r, 'c': c, 'type': '?'}
                obj['cells'].append((r, c))
                visited.add((r, c))

                # BFS to find connected component
                queue = [(r, c)]
                while queue:
                    cr, cc = queue.pop(0)
                    for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:  # right, down, left, up
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if (nr, nc) not in visited and grid[nr][nc] == color:
                                visited.add((nr, nc))
                                obj['cells'].append((nr, nc))
                                queue.append((nr, nc))

                # Determine shape type (only 2-cell objects)
                if len(obj['cells']) == 2:
                    d = tuple(sorted(obj['cells']))
                    d0, d1 = d[0], d[1]
                    pairs = (d1[0] - d0[0], d1[1] - d0[1])
                    if pairs == (0, 1):
                        obj['type'] = 'horizontal_pair'
                    elif pairs == (1, 0):
                        obj['type'] = 'vertical_pair'
                    else:
                        obj['type'] = f'other:{pairs}'
                objects.append(obj)

    return objects

objects = find_connected_objects(input_grid)
print(f"Total objects found: {len(objects)}")
